    oracle.insert(key, value);
    assert_eq!(map.iter().map(|(key, value)| (key.clone(), value.clone())).collect::<BTreeMap<_, _>>(), oracle);
    assert!(cursor.begin_close());
    close_insert(&mut cursor);assert!(cursor.terminal_is_empty());
}

